import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"development/architecture.md","filePath":"development/architecture.md"}'),s={name:"development/architecture.md"};function d(n,e,i,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Sky Style is an npm-workspace monorepo. Next.js serves the product and public API; VitePress builds the documentation independently.</p><h2 id="source-layout" tabindex="-1">Source layout <a class="header-anchor" href="#source-layout" aria-label="Permalink to &quot;Source layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>apps/web/src/app</code></td><td>Product pages, server actions and API route handlers</td></tr><tr><td><code>apps/web/src/components</code></td><td>Style, Closet, Shop and shared interface components</td></tr><tr><td><code>apps/web/src/lib</code></td><td>Weather/AI adapters, validation, usage and domain logic</td></tr><tr><td><code>apps/web/src/auth.ts</code></td><td>Auth.js providers, adapter and JWT session callbacks</td></tr><tr><td><code>apps/docs</code></td><td>Public documentation source and VitePress configuration</td></tr><tr><td><code>supabase</code></td><td>Database SQL assets, migration records and database tests</td></tr></tbody></table><h2 id="authentication-and-requests" tabindex="-1">Authentication and requests <a class="header-anchor" href="#authentication-and-requests" aria-label="Permalink to &quot;Authentication and requests&quot;">​</a></h2><p>Account pages use Auth.js JWT sessions. GitHub and Google are the available sign-in methods. Server pages use <code>auth()</code>; clients read <code>/api/auth/session</code>.</p><p>Session routes such as <code>/api/style</code> and <code>/api/shop</code> authenticate the account, validate input and enforce its available usage before provider work. The <a href="./../api/">public API</a> lives under <code>/api/v1</code> and uses API-key authentication. <a href="./../api/health.html">Health endpoints</a> are public read-only diagnostics and require no key.</p><h2 id="providers-and-recommendations" tabindex="-1">Providers and recommendations <a class="header-anchor" href="#providers-and-recommendations" aria-label="Permalink to &quot;Providers and recommendations&quot;">​</a></h2><p>Weather adapters normalise provider data before the AI receives it. The AI module defines model priorities, plan access and bring-your-own-key support. Provider availability depends on deployment configuration; a static model list is not evidence that a provider is connected.</p><p>Clothing actions resolve against the account&#39;s closet. Owned items open Closet; other items prepare an editable Shop search. Shop ranks source-supplied candidates and never uses AI text as a substitute for product prices, links or images.</p><h2 id="data-and-usage" tabindex="-1">Data and usage <a class="header-anchor" href="#data-and-usage" aria-label="Permalink to &quot;Data and usage&quot;">​</a></h2><p>Supabase stores account profiles, settings, closet items, usage, support records and changelog posts. Its admin client is server-only. Route-level account authorization and ownership checks remain necessary alongside database policies. Upserts declare their conflict target.</p><p>Usage helpers enforce the account&#39;s applicable allowance or credits. The UI should display the server&#39;s current usage readout rather than calculating access from marketing copy. Credit purchases and checkout are unavailable.</p><p>Optional preferences and BYOK keys use browser storage with the <code>skystyle_</code> prefix. User-provided keys pass through the server for a requested provider call and are not saved in the database. See <a href="./../web-app/security-and-privacy.html">Security &amp; Privacy</a>.</p><h2 id="developer-tools-and-background-work" tabindex="-1">Developer tools and background work <a class="header-anchor" href="#developer-tools-and-background-work" aria-label="Permalink to &quot;Developer tools and background work&quot;">​</a></h2><p>The Dev Center uses a shared, server-protected layout with task-based navigation. Each workspace has its own URL. API handlers independently authorize developer actions. See the <a href="./../web-app/dev-center.html">Dev Center guide</a>.</p><p>Automatic recommendations use a Supabase Cron worker. The <a href="./index.html#hosting-and-background-jobs">contributor overview</a> describes scheduling. Jest tests live beside library, component and route code; use the <a href="./testing.html">testing guide</a> to verify changes.</p>',17)])])}const b=a(s,[["render",d]]);export{h as __pageData,b as default};
